/bin/bash -lc "cd [workspace path] && python << 'EOF'
import numpy as np
d = np.load('source_pixels.npz')
a = d['rgb'].astype(int)
N,H,W,_ = a.shape

def track(cond):
    out=[]
    for i in range(N):
        ys,xs = np.where(cond(a[i]))
        if len(xs)==0:
            out.append((np.nan,np.nan,0))
        else:
            out.append((xs.mean(), ys.mean(), len(xs)))
    return out

R,G,B = a[:,:,:,0],a[:,:,:,1],a[:,:,:,2]
red = (R>150)&(G<110)&(B<110)
blue = (B>170)&(R<150)&(G>100)
white = (R>235)&(G>235)&(B>230)
# restrict to table area to avoid red arcade machine: table roughly y 40..120, x 20..240
def track_mask(mask, y0=35,y1=125,x0=15,x1=245):
    out=[]
    for i in range(N):
        m = mask[i,y0:y1,x0:x1]
        ys,xs = np.where(m)
        if len(xs)==0: out.append((np.nan,np.nan,0))
        else: out.append((xs.mean()+x0, ys.mean()+y0, len(xs)))
    return np.array(out)

rt = track_mask(red)
bt = track_mask(blue)
wt = track_mask(white)
for i in range(0,96,4):
    print(i, 'red', np.round(rt[i],1), 'blue', np.round(bt[i],1), 'white', np.round(wt[i],1))
EOF"
